const welcomeMessages = {
  russian: 'Добро пожаловать',
  english: 'Welcome',
  french: 'Bienvenue',
  italian: 'Benvenuto',
  spanish: 'bienvenido',
  chinese: '歡迎',
  finnish: 'Tervetuloa'
};

function deleteWelcomeMessages(propsArr) {
  propsArr.forEach(function (prop) {
    delete welcomeMessages[prop];
  });
}

deleteWelcomeMessages(['italian', 'french']);

console.log(welcomeMessages);

